head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[p > M > executeWhilst]<br/>파라미터의 조건 함수가 true 를 반환하는 동안 특정 Submission 을 반복적으로 실행합니다.",
    "validation" : [
        "condFunc 파라미터의 조건 함수와 maxRepeat 파라미터의 최대 횟수를 함께 적용합니다.",
        "submissionId(필수) 파라미터로 반복 실행할 submission 의 ID 를 설정할 수 있어야 합니다.",
        "condFunc(필수) 파라미터로 Submission 의 실행 여부를 판단하는 조건 함수를 설정할 수 있어야 하며, true 반환 시 Submission 을 계속 실행해야 합니다.",
        "maxRepeat(필수) 파라미터로 Submission 의 최대 반복 횟수를 설정할 수 있어야 하며, 무한 루프 방지 용도로도 사용 가능해야 합니다.",
        "processMsg(선택) / resolveCallback(선택) / rejectCallback(선택) / id(선택) 파라미터를 설정할 수 있어야 합니다.",
        "condFunc 조건 함수와 maxRepeat 최대 횟수 조건을 둘 다 만족해야 반복이 계속되어야 합니다.",
        "Submission 객체를 찾지 못하면 실행하지 않아야 합니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_executeWhilst_onclick = function () {
    var scenario = par_scenario.getValue();

    if (scenario === "1") {
        // 시나리오 1 : condFunc 로 반복 종료 (3회 반복 후 false)
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 1 : condFunc 로 반복 종료 (cnt < 3) ──");
        $p.executeWhilst(
            "sbm_whilst",
            function (subId, cnt) { return cnt < 3; },
            10,
            "$blank",
            function (workflowObj) {
                wf_body_bottom.getObj("scwin").setReturnValue(
                    "resolveCallback 호출됨 / workflowObj.result.length = " + workflowObj.result.length + " (반복 횟수)"
                );
            },
            function (workflowObj) {
                wf_body_bottom.getObj("scwin").setReturnValue("rejectCallback 호출됨");
            },
            "whilst_scenario1"
        );
    } else if (scenario === "2") {
        // 시나리오 2 : maxRepeat 으로 반복 종료 (condFunc 항상 true, maxRepeat 5)
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 2 : maxRepeat 으로 반복 종료 (maxRepeat=5) ──");
        $p.executeWhilst(
            "sbm_whilst",
            function (subId, cnt) { return true; },
            5,
            "$blank",
            function (workflowObj) {
                wf_body_bottom.getObj("scwin").setReturnValue(
                    "resolveCallback 호출됨 / workflowObj.result.length = " + workflowObj.result.length + " (반복 횟수)"
                );
            },
            function (workflowObj) {
                wf_body_bottom.getObj("scwin").setReturnValue("rejectCallback 호출됨");
            },
            "whilst_scenario2"
        );
    } else if (scenario === "3") {
        // 시나리오 3 : condFunc 첫 실행부터 false (cnt < 0)
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 3 : condFunc 첫 실행부터 false (cnt < 0) ──");
        $p.executeWhilst(
            "sbm_whilst",
            function (subId, cnt) { return cnt < 0; },
            10,
            "$blank",
            function (workflowObj) {
                wf_body_bottom.getObj("scwin").setReturnValue(
                    "resolveCallback 호출됨 / workflowObj.result.length = " + workflowObj.result.length + " (반복 횟수)"
                );
            },
            function (workflowObj) {
                wf_body_bottom.getObj("scwin").setReturnValue("rejectCallback 호출됨");
            },
            "whilst_scenario3"
        );
    } else if (scenario === "4") {
        // 시나리오 4 : 존재하지 않는 submissionId (Submission 객체 미존재 → 실행되지 않음)
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 4 : 존재하지 않는 submissionId ──");

        var called = { resolve : false, reject : false };

        $p.executeWhilst(
            "sbm_not_exist",
            function (subId, cnt) { return cnt < 3; },
            10,
            "$blank",
            function (workflowObj) {
                called.resolve = true;
                wf_body_bottom.getObj("scwin").setReturnValue("resolveCallback 호출됨 (예상 : 미호출)");
            },
            function (workflowObj) {
                called.reject = true;
                wf_body_bottom.getObj("scwin").setReturnValue("rejectCallback 호출됨 (예상 : 미호출)");
            },
            "whilst_scenario4"
        );

        // 500ms 대기 후 콜백 호출 여부 확인
        setTimeout(function () {
            wf_body_bottom.getObj("scwin").setReturnValue(
                "500ms 경과 후 resolveCallback/rejectCallback 미호출 (submission 미존재) : " +
                "resolve=" + called.resolve + ", reject=" + called.reject
            );
        }, 500);
    } else if (scenario === "5") {
        // 시나리오 5 : 선택 파라미터(processMsg / rejectCallback / id) 설정
        // - submission 의 action 을 존재하지 않는 URL 로 하여 submit 오류 발생 → rejectCallback 호출 유도
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 5 : 선택 파라미터(processMsg / rejectCallback / id) 설정 ──");

        var customId = "whilst_customId";

        // 오류 유발용 동적 submission 생성 (존재하지 않는 URL)
        $p.createSubmission({
            id : "sbm_whilst_fail",
            action : "/data/p_whilst_not_exist.json",
            method : "post",
            mediatype : "application/json"
        });

        $p.executeWhilst(
            "sbm_whilst_fail",
            function (subId, cnt) { return cnt < 3; },
            10,
            "Whilst Processing...",
            function (workflowObj) {
                wf_body_bottom.getObj("scwin").setReturnValue("resolveCallback 호출됨 (예상 : rejectCallback)");
                $p.hideProcessMessage();
            },
            function (workflowObj) {
                var wfId = (workflowObj && workflowObj.id) ? workflowObj.id : "-";
                wf_body_bottom.getObj("scwin").setReturnValue("rejectCallback 호출됨 (submit 오류 발생)");
                wf_body_bottom.getObj("scwin").setReturnValue("workflowObj.id : '" + wfId + "' / customId 일치 여부 : " + (wfId === customId));
                $p.hideProcessMessage();
            },
            customId
        );
    }
};
